{"cells":[{"cell_type":"code","source":"import os\nfrom openai import AsyncAzureOpenAI\nfrom dotenv import load_dotenv\n\nload_dotenv()\n\n# Azure OpenAI configuration\nAZURE_OPENAI_ENDPOINT = os.getenv(\"AZURE_OPENAI_ENDPOINT\")\nAZURE_OPENAI_API_KEY = os.getenv(\"AZURE_OPENAI_API_KEY\")\nAPI_VERSION = \"2024-02-01\"\nMODEL_NAME = \"gpt-4\"\n\nclient = AsyncAzureOpenAI(\n    azure_endpoint=AZURE_OPENAI_ENDPOINT,\n    api_key=AZURE_OPENAI_API_KEY,\n    api_version=API_VERSION,\n)\n\nasync def generate_response(query: str, file_url: str = None) -> str:\n    messages = [\n        {\"role\": \"system\", \"content\": \"You are a helpful assistant.\"}\n    ]\n\n    if file_url:\n        messages.append({\"role\": \"user\", \"content\": f\"Please analyze the content from this URL: {file_url}\"})\n\n    messages.append({\"role\": \"user\", \"content\": query})\n\n    try:\n        response = await client.chat.completions.create(\n            model=MODEL_NAME,\n            messages=messages\n        )\n        return response.choices[0].message.content\n    except Exception as e:\n        print(f\"Error generating response from OpenAI: {e}\")\n        return \"Sorry, I encountered an error while processing your request.\"","outputs":[],"execution_count":null,"metadata":{}}],"metadata":{"colab":{"from_bard":true},"kernelspec":{"display_name":"Python 3","name":"python3"}},"nbformat":4,"nbformat_minor":0}